import clsx from 'clsx';
import React, { ElementType, forwardRef, ReactElement } from 'react';

import { linkCSS } from './Link.sty.js';
import { useFocusRing } from '../core/styles/useFocusRing.js';
import type { DataTestId } from '../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../core/types/polymorph.js';
import type { StylingProps } from '../core/types/styling-props.js';
import type { WithChildren } from '../core/types/with-children.js';
import { mergeProps as _mergeProps } from '../core/utils/merge-props.js';

export type LinkProps<E extends ElementType> = PolymorphicComponentProps<
  E,
  WithChildren & StylingProps & DataTestId
>;

/**
 * Use the `Link` component to navigate to a different page within the application.
 * For external resources in a different domain, use the
 * {@link https://developer.dynatrace.com/reference/design-system/preview/typography/ExternalLink/ | `ExternalLink` }
 * component instead.
 */
export const Link: <E extends ElementType = 'a'>(
  props: LinkProps<E>,
) => ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends ElementType>(
    {
      children,
      as,
      'data-testid': dataTestId,
      className: consumerClassName,
      style: consumerStyle,
      ...remainingProps
    }: LinkProps<E>,
    ref: typeof remainingProps.ref,
  ) => {
    const { focusProps, focusClassName } = useFocusRing({
      variant: 'primary',
      isMinimal: true,
    });
    const LinkTag = as || 'a';

    return (
      <LinkTag
        ref={ref}
        data-testid={dataTestId}
        className={clsx(focusClassName, linkCSS, consumerClassName)}
        style={consumerStyle}
        {..._mergeProps(
          // Need to cast this one as the inference of mergeProps would generate
          // a not allowed overlap. The remainingProps type is too complex due to the
          // polymorphic inheritance.
          remainingProps as Record<string, unknown>,
          focusProps,
        )}
      >
        {children}
      </LinkTag>
    );
  },
);

(Link as typeof Link & { displayName: string }).displayName = 'Link';
